// Author: MiYu. Real source forms exercise identity, type consumers, bounded landing and timed hero restoration.
#include "session.h"
#include "setup.h"
#include <algorithm>
#include <bit>
#include <cmath>
#include <iostream>
using namespace war3;
int wmain(int argc,wchar_t** argv){
    try{
        if(argc<3 || argc>4)throw std::runtime_error("Usage: war3_unit_forms_tests <data-root> <fixture> [submerge]");if(argc==4 && std::wstring(argv[3])!=L"submerge")throw std::runtime_error("Unknown form check mode");Archives archives(argv[1]);archives.mountMap(argv[2]);auto world=World::read(archives);auto info=world->data().info;ScriptSession session(jass::Module::compile(jass::Program::read(archives)),info);session.attachWorld(std::move(world));session.audioMuted(true);session.configure();PlayerSetup setup(info,session.config());session.applySetup(setup);session.startMain();auto& vm=session.runtime();auto call=[&](const char* name,std::initializer_list<jass::Value> args){return vm.invoke(name,{args.begin(),args.size()});};auto require=[](bool value,const char* message){if(!value)throw std::runtime_error(message);};auto number=[](jass::Real value){return std::bit_cast<float>(value.bits());};auto real=[&](float value){return vm.real(jass::Real::fromBits(std::bit_cast<std::uint32_t>(value)));};auto type=[&](const char* value){return vm.integer(int(ObjectData::code(value)));};auto order=[&](jass::Value unit,const char* value){require(call("IssueImmediateOrder",{unit,vm.string(value)}).bits!=0,"Original form order rejected");};auto bear=vm.global("bear"),crow=vm.global("crow"),demon=vm.global("demon");auto b=session.units().at(bear.bits),c=session.units().at(crow.bits),d=session.units().at(demon.bits);
        if(argc==4){auto player=call("Player",{vm.integer(0)});call("SetPlayerTechResearched",{player,type("Rnsb"),vm.integer(1)});auto& pathWorld=*session.world();auto& path=*pathWorld.data().pathing;auto& terrain=pathWorld.data().terrain;std::optional<WorldPoint> land,water;for(unsigned y=4;y+4<path.height && (!land || !water);++y)for(unsigned x=4;x+4<path.width && (!land || !water);++x){WorldPoint point{jass::Real::fromBits(std::bit_cast<std::uint32_t>(terrain.origin[0]+x*32.f+16)),jass::Real::fromBits(std::bit_cast<std::uint32_t>(terrain.origin[1]+y*32.f+16))};auto flags=pathWorld.pathMask(point);if((flags&0x42)==2 && !water)water=point;else if((flags&0x42)!=2 && !land)land=point;}require(land.has_value() && water.has_value(),"Fixture needs both land and deep water");for(auto [normal,alternate]:{std::pair{"nmyr","nmys"},std::pair{"nnrg","nnrs"},std::pair{"nsnp","nsbs"}}){auto unit=call("CreateUnit",{player,type(normal),vm.real(land->x),vm.real(land->y),real(0)});auto state=session.units().at(unit.bits);call("SetUnitPathing",{unit,vm.boolean(false)});auto submergeButton=[&](){auto buttons=session.abilityCommands(unit.bits,0);auto button=std::find_if(buttons.begin(),buttons.end(),[](auto& entry){return entry.type==ObjectData::code("Asb1") || entry.type==ObjectData::code("Asb2") || entry.type==ObjectData::code("Asb3");});require(button!=buttons.end(),"Submerge button missing");return button->enabled;};require((pathWorld.pathMask({state->x,state->y})&0x42)!=2 && !submergeButton(),"Submerge enabled on non-water terrain");require(!call("IssueImmediateOrder",{unit,vm.string("submerge")}).bits,"Submerge accepted non-water terrain");call("SetUnitPosition",{unit,vm.real(water->x),vm.real(water->y)});require((pathWorld.pathMask({state->x,state->y})&0x42)==2 && submergeButton(),"Submerge disabled on deep water");order(unit,"submerge");session.advance(2);require(state->type==ObjectData::code(alternate) && state->burrowed && session.unitInvisible(unit.bits) && !session.hasWeapon(unit.bits) && number(state->moveSpeed)==0,"Submerged source form, visibility, movement or weapon incorrect");order(unit,"unsubmerge");session.advance(2);require(state->type==ObjectData::code(normal) && !state->burrowed && !session.unitInvisible(unit.bits) && state->handle==unit.bits && number(state->moveSpeed)>0,"Surfacing did not restore unit identity and state");call("RemoveUnit",{unit});}auto alternate=call("CreateUnit",{player,type("nmys"),vm.real(land->x),vm.real(land->y),real(0)});auto submerged=session.units().at(alternate.bits);require((pathWorld.pathMask({submerged->x,submerged->y})&0x42)!=2 && session.unitInvisible(alternate.bits),"Initially submerged source form or non-water position incorrect");order(alternate,"unsubmerge");session.advance(2);require(session.units().at(alternate.bits)->type==ObjectData::code("nmyr"),"Initially submerged unit could not surface");std::cout<<"PASS naga_submerge_forms_visibility_and_identity\nRESULT passed=1 failed=0 game_dll_loaded=false\n";return 0;}
        call("SetUnitState",{bear,vm.handle("unitstate",0),real(number(b->maxLife)*.5f)});float ratio=number(b->life)/number(b->maxLife),mana=number(b->mana);int food=session.config().players[0].states.at(5);order(bear,"bearform");session.advance(3);require(b->type==ObjectData::code("edcm") && !b->formTransition && number(b->maxLife)>800 && std::abs(number(b->life)/number(b->maxLife)-ratio)<.02f && b->sequenceName("Stand")=="Stand Alternate","Bear Form did not change real type, health ratio and animation");require(number(b->mana)<mana-20 && session.config().players[0].states.at(5)==food,"Bear form cost or population changed incorrectly");require(!call("IssueImmediateOrder",{bear,vm.string("bearform")}).bits,"Forward order toggled an already active form");call("SetUnitState",{bear,vm.handle("unitstate",2),real(0)});auto buttons=session.abilityCommands(bear.bits,0);auto button=std::find_if(buttons.begin(),buttons.end(),[](auto& entry){return entry.type==ObjectData::code("Abrf");});require(button!=buttons.end() && button->enabled && !button->icon.empty(),"Free reverse form button is missing");order(bear,"unbearform");session.advance(3);require(b->type==ObjectData::code("edoc") && !b->unitForm && b->animationProperties.empty() && b->handle==bear.bits,"Bear reverse did not preserve identity or restore normal type");std::cout<<"PASS bear_orders_type_health_ratio_population_free_reverse_and_animation\n";
        order(crow,"ravenform");session.advance(.95);require(c->airborne() && c->formTransition && c->flyHeight>0,"Crow immediate takeoff and height interpolation were not consumed");session.advance(2);require(c->type==ObjectData::code("edtm") && std::abs(c->flyHeight-240)<.01f && number(c->moveSpeed)>=350 && c->animationProperties=="Alternate","Crow source flying type, speed or height missing");order(crow,"unravenform");session.advance(3);require(c->type==ObjectData::code("edot") && !c->airborne() && c->flyHeight==0 && !c->formTransition,"Crow did not land and restore the ground form");std::cout<<"PASS crow_takeoff_height_speed_and_ground_landing\n";
        auto attributes=d->heroAttributes;auto experience=d->experience;auto level=d->level;float maximum=number(d->maxLife);call("UnitAddAbility",{demon,type("AInv")});auto item=call("UnitAddItemById",{demon,type("phea")});order(demon,"metamorphosis");session.advance(3);require(d->type==ObjectData::code("Edmm") && d->unitForm && d->unitForm->active && std::abs(number(d->maxLife)-maximum-500)<.01f && d->heroAttributes==attributes && d->level==level && d->experience==experience && d->inventory[0]==item.bits,"Metamorphosis lost hero identity, growth, inventory or health bonus");require(!session.castSpell(demon.bits,ObjectData::code("AEme")),"Active Metamorphosis recast was accepted");session.advance(60);session.advance(3);require(d->type==ObjectData::code("Edem") && !d->unitForm && !d->formTransition && std::abs(number(d->maxLife)-maximum)<.01f && number(d->life)>0 && d->heroAttributes==attributes && d->inventory[0]==item.bits,"Metamorphosis expiry did not restore the original hero");call("UnitResetCooldown",{demon});call("SetUnitState",{demon,vm.handle("unitstate",2),real(200)});order(demon,"metamorphosis");session.advance(3);call("KillUnit",{demon});require(d->type==ObjectData::code("Edem") && !d->unitForm && !d->formTransition && number(d->life)==0 && std::abs(number(d->maxLife)-maximum)<.01f,"Metamorphosis death did not restore normal revival state");std::cout<<"PASS metamorphosis_growth_inventory_health_expiry_and_death\n";
        if(GetModuleHandleW(L"Game.dll"))throw std::runtime_error("Game.dll loaded");std::cout<<"RESULT passed=3 failed=0 game_dll_loaded=false\n";return 0;
    }catch(const std::exception& error){std::cerr<<"FAIL "<<error.what()<<'\n';return 1;}
}
